ALTER TABLE public.hr_shifts ADD COLUMN no_show_decision text CHECK(no_show_decision IN ('unpaid','leave','swap')),ADD COLUMN no_show_decided_by uuid,ADD COLUMN no_show_decided_at timestamptz;
CREATE FUNCTION public.rota_no_show_decision(t uuid,sid uuid,decision text,replacement uuid DEFAULT NULL,leave_kind text DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.hr_shifts;v uuid;BEGIN SELECT * INTO s FROM public.hr_shifts WHERE tenant_id=t AND id=sid FOR UPDATE;v:=COALESCE(s.venue_id,(SELECT venue_id FROM public.hr_employees WHERE tenant_id=t AND id=s.employee_id));IF s.id IS NULL OR NOT public.rota_manager(t,v,auth.uid()) OR NOT public.people_person_access(t,s.employee_id,auth.uid()) OR decision NOT IN ('unpaid','leave','swap') OR s.shift_type<>'regular' OR s.no_show_decision IS NOT NULL OR public.people_effective_settings(t,v)->>'clock_in'='off' THEN RAISE EXCEPTION 'No-show decision unavailable';END IF;IF ((s.shift_date+CASE WHEN s.end_time<s.start_time THEN 1 ELSE 0 END)+s.end_time)>(now() AT TIME ZONE 'Asia/Hong_Kong') OR EXISTS(SELECT 1 FROM public.hr_attendance WHERE tenant_id=t AND employee_id=s.employee_id AND date=s.shift_date AND clock_in IS NOT NULL) THEN RAISE EXCEPTION 'No-show evidence changed; reload';END IF;IF decision='swap' THEN IF replacement IS NULL OR replacement=s.employee_id THEN RAISE EXCEPTION 'Choose the person who covered';END IF;PERFORM public.rota_swap(t,sid,replacement,NULL,true);ELSIF decision='leave' THEN IF leave_kind IS NULL THEN RAISE EXCEPTION 'Choose leave type';END IF;PERFORM public.rota_leave(t,s.employee_id,leave_kind,s.shift_date,s.shift_date,NULL,true);ELSE UPDATE public.hr_shifts SET shift_type='NPL' WHERE tenant_id=t AND id=sid;END IF;UPDATE public.hr_shifts SET no_show=decision<>'swap',no_show_decision=decision,no_show_decided_by=auth.uid(),no_show_decided_at=now() WHERE tenant_id=t AND id=sid;END $$;
REVOKE ALL ON FUNCTION public.rota_no_show_decision(uuid,uuid,text,uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.rota_no_show_decision(uuid,uuid,text,uuid,text) TO authenticated;